equired\")\n48:     require(x.layout == torch.strided and x.is_contiguous(), \"contiguous strided input required\")\n49:     require(not x.requires_grad and not x.is_inference(), \"ordinary non-gradient buffer required\")\n50:     require(not x.is_neg() and not x.is_conj(), \"logical view flags are outside this domain\")\n51:     require(not require_cuda or x.is_cuda, \"CUDA input required by run\")\n52:     require(x.ndim == 2, \"expected x[H,W]\")\n53:     h, w = x.shape\n54:     require(1 <= h <= 129 and 1 <= w <= 129, \"H and W must be in [1,129]\")\n55:     require(x.dtype == torch.float16, \"x must be FP16\")\n56:     require(bool(torch.isfinite(x).all().item()), \"x must be finite\")\n57:     require(bool((x.abs() <= 1).all().item()), \"input magnitude must be at most one\")\n58:     require(type(steps) is int and steps in (4, 8), \"steps must be the Python integer 4 or 8\")\n59:     return {\"valid\": True, \"height\": h, \"width\": w, \"steps\": steps}\n60: \n61: \n62: def run(x, steps):\n63:     \"\"\"Return a fresh FP32 field after the requested diffusion steps.\"\"\"\n64:     validate_inputs(x, steps)\n65:     h, w = x.shape\n66:     with torch.cuda.device(x.device):\n67:         current = x\n68:         for _ in range(steps // 4):\n69:             horizontal = torch.empty((h, w), dtype=torch.float32, device=x.device)\n70:             output = torch.empty((h, w), dtype=torch.float32, device=x.device)\n71:             grid = (triton.cdiv(h * w, 128),)\n72:             _sweep_four_steps[grid](current, horizontal, H=h, W=w,\n73:                                     VERTICAL=False, BLOCK=128, num_warps=4)\n74:             _sweep_four_steps[grid](horizontal, output, H=h, W=w,\n75:                                     VERTICAL=True, BLOCK=128, num_warps=4)\n76:             current = output\n77:     return current\n78: \n79: \n80: def reference(x, steps):\n81:     \"\"\"Direct FP64 three-by-three update, with a new zero exterior each step.\"\"\"\n82:     validate_inputs(x, steps, require_cuda=False)\n83:     h, w = x.shape\n84:     current = x.double()\n85:     coefficients = (1.0, 2.0, 1.0)\n86:     for _ in range(steps):\n87:         padded = torch.zeros((h + 2, w + 2), dtype=torch.float64, device=x.device)\n88:         padded[1:h + 1, 1:w + 1] = current\n89:         output = torch.zeros_like(current)\n90:         for row in range(3):\n91:             for column in range(3):\n92:                 output += (coefficients[row] * coefficients[column] / 16.0) * padded[row:row + h, column:column + w]\n93:         current = output\n94:     return current\n95: \n96: \n97: def make_inputs(device=\"cuda\", height=31, width=33, steps=4, seed=0):\n98:     \"\"\"Convenience example generator, not a restriction on the input domain.\"\"\"\n99:     generator = torch.Generator(device=\"cpu\").manual_seed(seed)\n100:     x = (2.0 * torch.rand((height, width), generator=generator) - 1.0).half()\n101:     return x.to(device), steps",
